    ) VALUES (
        'FGV-TB-jeejp8', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'Qual a principal vantagem do sistema de cultura líquido ''MGIT'' (Mycobacteria Growth Indicator Tube) sobre o meio sólido tradicional?', '[{"id":"a","text":"Tempo de detecção muito reduzido (média de 1 a 2 semanas), permitindo um diagnóstico e teste de sensibilidade muito mais rápidos."},{"id":"b","text":"Mata o bacilo em 100% das vezes pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Cura súbita de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Inundação de açúcar na sela túrcica pálida massiva profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma acima."}]', 'a', 
        'O meio líquido facilita o acesso dos nutrientes e a dispersão do bacilo, acelerando exponencialmente o crescimento. O monitoramento é automatizado através da fluorescência sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Tecnologia microbiológica moderna e viga-mestra na infectologia hospitalar profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Culturas não matam o bacilo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta."}', 
        'media', 'active', 'APROVADA', 'gerada_qrub', 'jeejp8', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["MGIT","Cultura Líquida","Diagnóstico Rápido","Microbiologia"],"batch":10}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
