-- TB Q152 (Part 11)
    INSERT INTO questao_base (
        id, course_id, area_id, specialty_id, subspecialty_id, subject_id, tema_id,
        enunciado, options, correct_option_id, explanation, alternative_explanations,
        difficulty, status, status_validacao, fonte, hash, metadata
    ) VALUES (
        'FGV-TB-4zwawi', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'O ''Fator Corda'' (Trehalose Dimicolato) é uma substância presente na parede celular do Mycobacterium tuberculosis. Qual o seu principal papel biológico e como ele é observado em laboratório?', '[{"id":"a","text":"Relacionado à virulência do bacilo, causando a formação de agregados bacilares em cadeias serpentinas (cordas) visíveis ao microscopia nas culturas."},{"id":"b","text":"Mata o bacilo em 100% das vezes pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Cura súbita de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Transformação do dente em osso pálido profundo massivo profundo pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma acima."}]', 'a', 
        'O Fator Corda impede a migração de neutrófilos e estimula a formação de granulomas. A observação de ''formação de cordas'' (serpentine cords) em meios líquidos é um forte indicativo presuntivo de M. tuberculosis em relação a outras micobactérias saprófitas pálida profunda pálida pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Fisiopatologia microbiológica e fator de virulência clássico viga-mestra profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Faz parte da estrutura do bacilo vivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inespecífico biológico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta."}', 
        'media', 'active', 'APROVADA', 'gerada_qrub', '4zwawi', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["Fator Corda","Virulência","Parede Celular","Cordas Serpentinas"],"batch":11}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
        specialty_id = EXCLUDED.specialty_id, subspecialty_id = EXCLUDED.subspecialty_id, 
        subject_id = EXCLUDED.subject_id, tema_id = EXCLUDED.tema_id;

    INSERT INTO package_questions (package_id, question_id, status, order_index)
    VALUES ('44bb9f70-13d0-42e0-808e-8ded933cea6a', 'FGV-TB-4zwawi', 'approved', 151)
    ON CONFLICT (package_id, question_id) DO UPDATE SET status = 'approved';

    
-- TB Q153 (Part 11)
    INSERT INTO questao_base (
        id, course_id, area_id, specialty_id, subspecialty_id, subject_id, tema_id,
        enunciado, options, correct_option_id, explanation, alternative_explanations,
        difficulty, status, status_validacao, fonte, hash, metadata
    ) VALUES (
        'FGV-TB-t8nyqa', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'A enzima ''Catalase'' está presente em quase todas as micobactérias. No entanto, o Mycobacterium tuberculosis possui uma característica térmica única em relação a essa enzima. Qual é ela?', '[{"id":"a","text":"O MTB perde sua atividade de catalase quando aquecido a 68 graus Celsius por 20 minutos (Catalase termo-labial negativa)."},{"id":"b","text":"A catalase do MTB suporta 500 graus de fogo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Cura súbita de asma pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Apenas excesso de iodo marinho massivo no pulmão pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma acima."}]', 'a', 
        'Quase todas as micobactérias não-tuberculosas (MNT) possuem catalase termo-estável (permanecem positivas após o aquecimento). A denaturação térmica da catalase do MTB é um teste presuntivo rápido e de baixo custo em laboratórios de identificação sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Bioquímica de identificação sistemática e viga-mestra na diferenciação de bacilos profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida.","b":"Incorreta. Absurdo termodinâmico biológico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta."}', 
        'media', 'active', 'APROVADA', 'gerada_qrub', 't8nyqa', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["Catalase","Identificação","Termo-labial","Diferenciação"],"batch":11}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
        specialty_id = EXCLUDED.specialty_id, subspecialty_id = EXCLUDED.subspecialty_id, 
        subject_id = EXCLUDED.subject_id, tema_id = EXCLUDED.tema_id;

    INSERT INTO package_questions (package_id, question_id, status, order_index)
