-- TB Q155 (Part 11)
    INSERT INTO questao_base (
        id, course_id, area_id, specialty_id, subspecialty_id, subject_id, tema_id,
        enunciado, options, correct_option_id, explanation, alternative_explanations,
        difficulty, status, status_validacao, fonte, hash, metadata
    ) VALUES (
        'FGV-TB-f23h0z', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'A coloração por ''Auramina-Rodamina'' utiliza a propriedade de fluorescência para detectar micobactérias. Qual a principal vantagem desta técnica sobre a coloração tradicional de Ziehl-Neelsen no laboratório clínico?', '[{"id":"a","text":"Maior sensibilidade e rapidez, permitindo rastrear o esfregaço em menor magnificação (objetivas de 25x ou 40x), cobrindo uma área maior da lâmina em menos tempo."},{"id":"b","text":"Transformar o bacilo em diamante pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Cura súbita de miopia pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Apenas iodo marinho massivo no pulmão pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma vantagem; o custo inviabiliza o uso em massa pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."}]', 'a', 
        'A fluorescência faz os bacilos brilharem intensamente no campo escuro, facilitando a visualização rápida. Enquanto o ZN exige imersão (100x), a Auramina permite ao técnico detectar bacilos mais raros de forma mais eficiente sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Técnica laboratorial de microscopia e viga-mestra no rastreamento rápido profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta. Em laboratórios de grande volume, a rapidez compensa o custo do microscópio de fluorescência sela túrcica profunda pálida profunda pálida profunda."}', 
        'media', 'active', 'APROVADA', 'gerada_qrub', 'f23h0z', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["Fluorescência","Auramina","Diagnóstico","Microscopia"],"batch":11}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
        specialty_id = EXCLUDED.specialty_id, subspecialty_id = EXCLUDED.subspecialty_id, 
        subject_id = EXCLUDED.subject_id, tema_id = EXCLUDED.tema_id;

    INSERT INTO package_questions (package_id, question_id, status, order_index)
    VALUES ('44bb9f70-13d0-42e0-808e-8ded933cea6a', 'FGV-TB-f23h0z', 'approved', 154)
    ON CONFLICT (package_id, question_id) DO UPDATE SET status = 'approved';

    
-- TB Q156 (Part 11)
    INSERT INTO questao_base (
        id, course_id, area_id, specialty_id, subspecialty_id, subject_id, tema_id,
        enunciado, options, correct_option_id, explanation, alternative_explanations,
        difficulty, status, status_validacao, fonte, hash, metadata
    ) VALUES (
        'FGV-TB-o0xm39', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'A ''Redução de Nitrato'' a nitrito é um teste fundamental na identificação de micobactérias. Como o M. tuberculosis se comporta neste teste bioquímico?', '[{"id":"a","text":"O MTB é fortemente positivo para a redução de nitrato (possui a enzima nitrato-redutase)."},{"id":"b","text":"Mata o bacilo em 100% das vezes pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Cura súbita de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Substituição do açúcar por iodo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma acima."}]', 'a', 
        'Junto com a niacina, a redução de nitrato é o pilar de identificação definitiva do MTB. A detecção dessa enzima permite diferenciar o MTB do complexo M. avium e de várias micobactérias de crescimento rápido sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Bioquímica diagnóstica e viga-mestra na taxonomia bacteriana infalível profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Bioquímica de metabolismo ativo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta."}', 
        'facil', 'active', 'APROVADA', 'gerada_qrub', 'o0xm39', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["Nitrato","MTB","Microbiologia","Metabolismo"],"batch":11}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
        specialty_id = EXCLUDED.specialty_id, subspecialty_id = EXCLUDED.subspecialty_id, 
