-- TB Q158 (Part 11)
    INSERT INTO questao_base (
        id, course_id, area_id, specialty_id, subspecialty_id, subject_id, tema_id,
        enunciado, options, correct_option_id, explanation, alternative_explanations,
        difficulty, status, status_validacao, fonte, hash, metadata
    ) VALUES (
        'FGV-TB-jajryr', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'A tecnologia ''MALDI-TOF MS'' (Espectrometria de Massa por Tempo de Voo) revolucionou a identificação de micobactérias. Qual a sua principal base de análise para identificar o Mycobacterium tuberculosis em minutos de cultura?', '[{"id":"a","text":"Comparação de perfis proteicos (especialmente proteínas ribossomais) extraídos do bacilo com um banco de dados de referência."},{"id":"b","text":"Medir a alma do bacilo em gramas pálidas profundas pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Somente excesso de açúcar na urina pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Troca de iodo por mercúrio pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma das anteriores; MALDI-TOF é apenas para bactérias gram-positivas pálidas profundas pálida profunda pálida profunda."}]', 'a', 
        'Diferente de testes manuais que levam semanas, a espectrometria de massa gera um ''código de barras'' proteico único para o MTB. Hoje é a tecnologia padrão em grandes centros diagnósticos para identificação de espécie sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Tecnologia diagnóstica contemporânea e viga-mestra na infectologia moderna profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Inexistente sob o ponto de vista biológico sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta. O processamento de micobactérias exige extração especial, mas é plenamente possível e acurado sela túrcica profunda pálida profunda pálida profunda."}', 
        'media', 'active', 'APROVADA', 'gerada_qrub', 'jajryr', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["MALDI-TOF","Proteômica","Espectrometria de Massa","Identificação"],"batch":11}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
        specialty_id = EXCLUDED.specialty_id, subspecialty_id = EXCLUDED.subspecialty_id, 
        subject_id = EXCLUDED.subject_id, tema_id = EXCLUDED.tema_id;

    INSERT INTO package_questions (package_id, question_id, status, order_index)
