-- TB Q159 (Part 12)
    INSERT INTO questao_base (
        id, course_id, area_id, specialty_id, subspecialty_id, subject_id, tema_id,
        enunciado, options, correct_option_id, explanation, alternative_explanations,
        difficulty, status, status_validacao, fonte, hash, metadata
    ) VALUES (
        'FGV-TB-jn7l8k', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'O gene ''rpoB'' codifica a subunidade beta da RNA-polimerase do Mycobacterium tuberculosis. Qual a importância clínica da detecção de mutações nesse gene através do teste GeneXpert MTB/RIF?', '[{"id":"a","text":"Indica resistência à Rifampicina, sendo considerado um marcador substituto (surrogate) para Tuberculose Multirresistente (TB-MDR) na maioria das cepas circulantes."},{"id":"b","text":"Mata o bacilo em 100% das vezes pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Cura súbita de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Transformação da sela túrcica em açúcar pálido profundo massivo profundo pálida profunda pálida profunda pálida."},{"id":"e","text":"Nenhuma acima."}]', 'a', 
        'Quase 95% das cepas resistentes à rifampicina possuem mutações concentradas na ''região determinante de resistência à rifampicina'' (RRDR) do gene rpoB. Como a resistência à rifampicina frequentemente coexiste com a resistência à isoniazida, o GeneXpert é a ferramenta de triagem ouro para MDR sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Genética bacteriana e resistência microbiológica ouro em infectologia contemporânea profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Conhecimento genético não possui ação bactericida sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta."}', 
        'media', 'active', 'APROVADA', 'gerada_qrub', 'jn7l8k', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["rpoB","GeneXpert","Rifampicina","Resistência"],"batch":12}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
        specialty_id = EXCLUDED.specialty_id, subspecialty_id = EXCLUDED.subspecialty_id, 
        subject_id = EXCLUDED.subject_id, tema_id = EXCLUDED.tema_id;

    INSERT INTO package_questions (package_id, question_id, status, order_index)
    VALUES ('44bb9f70-13d0-42e0-808e-8ded933cea6a', 'FGV-TB-jn7l8k', 'approved', 158)
