-- TB Q160 (Part 12)
    INSERT INTO questao_base (
        id, course_id, area_id, specialty_id, subspecialty_id, subject_id, tema_id,
        enunciado, options, correct_option_id, explanation, alternative_explanations,
        difficulty, status, status_validacao, fonte, hash, metadata
    ) VALUES (
        'FGV-TB-jymue3', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'As mutações nos genes ''katG'' e ''inhA'' conferem resistência a qual medicamento do esquema RIPE no Mycobacterium tuberculosis?', '[{"id":"a","text":"Isoniazida."},{"id":"b","text":"Rifampicina de cor negra pálida profunda massiva profunda pálida profunda."},{"id":"c","text":"Cura total de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Apenas reposição de mel pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma das anteriores."}]', 'a', 
        'A mutação no katG (especialmente a mutação S315T) inibe a enzima catalase-peroxidase que ativa a isoniazida (que é uma pró-droga). Mutações na região promotora de inhA causam resistência de baixo nível por superexpressão do alvo da droga. É o mecanismo molecular de sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Mecanismos moleculares de resistência farmacológica e viga-mestra na farmacologia da TB profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Rifampicina age na RNA-polimerase (rpoB) sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta."}', 
        'dificil', 'active', 'APROVADA', 'gerada_qrub', 'jymue3', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["katG","inhA","Isoniazida","Resistência"],"batch":12}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
        specialty_id = EXCLUDED.specialty_id, subspecialty_id = EXCLUDED.subspecialty_id, 
        subject_id = EXCLUDED.subject_id, tema_id = EXCLUDED.tema_id;

