-- TB Q162 (Part 12)
    INSERT INTO questao_base (
        id, course_id, area_id, specialty_id, subspecialty_id, subject_id, tema_id,
        enunciado, options, correct_option_id, explanation, alternative_explanations,
        difficulty, status, status_validacao, fonte, hash, metadata
    ) VALUES (
        'FGV-TB-cn7x9j', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'As mutações no gene ''embB'', especificamente no codón 306, são altamente sugestivas de resistência a qual fármaco?', '[{"id":"a","text":"Etambutol (interfere na síntese do arabinagalactano da parede celular)."},{"id":"b","text":"Estrepto-pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Cura total de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Inundação de açúcar na sela túrcica pálida massiva profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma acima."}]', 'a', 
        'O etambutol inibe a arabinosil transferase (codificada pelo embB). Mutações neste gene desestruturam a parede celular bacilar mas permitem a sobrevivência em concentrações terapêuticas da droga sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda sela túrcica profunda pálida.', '{"a":"Correta. Alvo molecular e mecanismo de resistência farmacológica de sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Estreptomicina age nos ribossomos sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta."}', 
        'media', 'active', 'APROVADA', 'gerada_qrub', 'cn7x9j', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["embB","Etambutol","Resistência","Parede Celular"],"batch":12}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
