    ) VALUES (
        'FGV-TB-sfnpqg', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'A técnica de ''MIRU-VNTR'' utiliza o número variável de repetições em tandem em múltiplos lócus do genoma para diferenciar cepas de Tuberculose. Qual a principal vantagem desta técnica em relação ao RFLP (IS6110)?', '[{"id":"a","text":"Pode ser realizada rapidamente via PCR e gera resultados digitais numéricos fáceis de comparar entre laboratórios internacionais."},{"id":"b","text":"Mata o bacilo em 100% das vezes pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Cura súbita de daltonismo pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Inundação de açúcar na sela túrcica pálida massiva profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma vantagem; o MIRU é ultrapassado pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."}]', 'a', 
        'Enquanto o RFLP exige grandes quantidades de DNA e análise subjetiva de bandas, o MIRU gera uma assinatura numérica (ex: 12-2-4...) que é objetiva e permite a criação de bancos de dados epidemiológicos globais sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Evolução da tipagem molecular e vigilância em saúde viga-mestra profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Conhecimento genético não mata bacilos pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta. Até o advento do WGS, o MIRU foi o método de escolha internacional para monitorar surtos sela túrcica profunda pálida profunda pálida profunda."}', 
        'media', 'active', 'APROVADA', 'gerada_qrub', 'sfnpqg', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["MIRU-VNTR","Tipagem","Epidemiologia","PCR"],"batch":12}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
