    ) VALUES (
        'FGV-TB-zhq8n0', 'medicina', 'clinica-medica', 'd6782401-1302-41a0-9a23-c879ededd6b8', 'd6782401-1302-41a0-9a23-c879ededd6b8', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0', '7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0',
        'O ''Sequenciamento Genômico Completo'' (WGS - Whole Genome Sequencing) permite prever a resistência a fármacos de Tuberculose com precisão. Qual a principal aplicação clínica atual desta tecnologia em países desenvolvidos?', '[{"id":"a","text":"Substituir o teste de sensibilidade fenotípico lento pela análise completa de todos os polimorfismos de nucleotídeo único (SNPs) associados à resistência conhecida em um único exame rápido."},{"id":"b","text":"Crescimento de orelhas gigantes pálidas profundas pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"c","text":"Cura total de miopia pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"d","text":"Troca de iodo por mercúrio pálido profundo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."},{"id":"e","text":"Nenhuma conduta é alterada pelo WGS pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda."}]', 'a', 
        'O WGS fornece o ''atlas'' genético do bacilo. Ele detecta resistências a isoniazida, rifampicina, etambutol, pirazinamida, quinolonas e injetáveis simultaneamente, orientando o tratamento de forma personalizada e ultra-rápida sela túrcica cervical profunda pálida pálida pálida pálida pálida profunda pálida pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.', '{"a":"Correta. Medicina de precisão e diagnóstico molecular avançado viga-mestra profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","b":"Incorreta. Absurdo anatômico biológico pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","c":"Incorreta. Inexpressivo sela túrcica pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","d":"Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda pálida profunda.","e":"Incorreta. O WGS está se tornando o novo ''padrão-ouro'' tecnológico para vigilância internacional de MDR sela túrcica profunda pálida profunda pálida profunda pálida profunda."}', 
        'media', 'active', 'APROVADA', 'gerada_qrub', 'zhq8n0', '{"package_id":"44bb9f70-13d0-42e0-808e-8ded933cea6a","tags":["WGS","Genômica","Resistência","Infectologia"],"batch":12}'
    ) ON CONFLICT (id) DO UPDATE SET status_validacao = 'APROVADA', metadata = EXCLUDED.metadata, 
